def verify_isbn(isbn: str) -> str:
    def calculate_checksum(isbn: str) -> int:
        # Remove hyphens and the last character (checksum)
        numbers = isbn.replace('-', '')[:-1]
        total = 0
        for i, num in enumerate(numbers):
            total += (i + 1) * int(num)
        checksum = total % 11
        return checksum

    def checksum_to_char(checksum: int) -> str:
        return 'X' if checksum == 10 else str(checksum)

    try:
        # Validate the format
        if len(isbn) != 13 or isbn[1] != '-' or isbn[5] != '-' or isbn[11] != '-':
            raise ValueError("ISBN format is incorrect")

        # Calculate the expected checksum
        expected_checksum = calculate_checksum(isbn)

        # Get the provided checksum
        provided_checksum_char = isbn[-1]
        provided_checksum = 10 if provided_checksum_char == 'X' else int(provided_checksum_char)

        # Compare checksums
        if expected_checksum == provided_checksum:
            return "Right"
        else:
            # Construct the corrected ISBN
            corrected_checksum_char = checksum_to_char(expected_checksum)
            corrected_isbn = isbn[:-1] + corrected_checksum_char
            return corrected_isbn

    except (ValueError, IndexError) as e:
        return f"Invalid ISBN: {str(e)}"

