def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    if not isinstance(n, int) or n < 0:
        raise ValueError("The highest degree n must be a non-negative integer.")
    if not isinstance(coeffs, list) or len(coeffs) != n + 1:
        raise ValueError("Coefficients must be a list of integers with length n+1.")

    terms = []
    for i, coeff in enumerate(coeffs):
        degree = n - i
        if coeff == 0:
            continue

        # Determine the sign
        sign = '+' if coeff > 0 else '-'
        if not terms:
            sign = '' if coeff > 0 else '-'

        # Determine the coefficient part
        abs_coeff = abs(coeff)
        coeff_str = ''
        if abs_coeff != 1 or degree == 0:
            coeff_str = str(abs_coeff)

        # Determine the variable part
        var_str = ''
        if degree > 1:
            var_str = f'x^{degree}'
        elif degree == 1:
            var_str = 'x'

        # Combine parts
        terms.append(f'{sign}{coeff_str}{var_str}')

    return ''.join(terms)

