def largest_prime_factor(n: int) -> int:
    if n <= 1:
        raise ValueError("Input must be a positive integer greater than 1.")

    # Start checking from the smallest prime number
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            # Since n is the product of exactly two distinct primes, n // i will be the larger prime
            return n // i

    # If no factors are found, n itself is a prime number (though the problem states n is a product of two distinct primes)
    return n

