        if in_start > in_end:
            return None

        nonlocal post_index
        root_val = postorder[post_index]
        root = Node(root_val)
        post_index -= 1

        if in_start == in_end:
            return root

        in_index = inorder_index_map[root_val]

        root.right = build_tree(in_index + 1, in_end)
        root.left = build_tree(in_start, in_index - 1)

        return root

    class Node:
        def __init__(self, value):
            self.value = value
            self.left = None
            self.right = None

    def preorder(node):
        if not node:
            return ""
        return node.value + preorder(node.left) + preorder(node.right)

    post_index = len(postorder) - 1
    inorder_index_map = {value: index for index, value in enumerate(inorder)}

    root = build_tree(0, len(inorder) - 1)
    return preorder(root)

