def generate_numbers(n, rules) -> int:
    from collections import deque, defaultdict

    # Create a transformation mapping for quick lookup
    transformation = defaultdict(set)
    for x, y in rules:
        transformation[x].add(y)

    # Convert the number to a string for easy manipulation
    original_number = str(n)
    length = len(original_number)

    # Initialize BFS queue and visited set
    queue = deque([original_number])
    visited = set([original_number])

    while queue:
        current_number = queue.popleft()

        # Try transforming each digit
        for idx in range(length):
            digit = int(current_number[idx])
            if digit in transformation:
                for new_digit in transformation[digit]:
                    new_number = current_number[:idx] + str(new_digit) + current_number[idx+1:]
                    if new_number not in visited:
                        visited.add(new_number)
                        queue.append(new_number)

    # Return the count of unique numbers generated
    return len(visited)

