def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    if T < 0 or M < 0 or len(herbs) != M:
        raise ValueError("Invalid input parameters")

    # Create a DP array to store the maximum value that can be achieved with a given time limit
    dp = [0] * (T + 1)

    for time, value in herbs:
        if time > T:
            continue
        # Update the dp array from the back to avoid overwriting values that we still need to use
        for t in range(T, time - 1, -1):
            dp[t] = max(dp[t], dp[t - time] + value)

    return dp[T]

