def min_groups(w, n, prices):
    if not isinstance(w, int) or not isinstance(n, int) or not isinstance(prices, list):
        raise ValueError("Invalid input types")
    if w <= 0 or n < 0:
        raise ValueError("w must be positive and n must be non-negative")
    if len(prices) != n:
        raise ValueError("Length of prices list must match n")
    if any(not isinstance(price, int) or price < 0 for price in prices):
        raise ValueError("All prices must be non-negative integers")

    prices.sort()
    left, right = 0, n - 1
    groups = 0

    while left <= right:
        if prices[left] + prices[right] <= w:
            left += 1
        right -= 1
        groups += 1

    return groups

